package viewpoint.world;
public final class ChunkCache{private static final java.util.HashMap<zombie.iso.IsoChunk,Entry> entries=new java.util.HashMap<>();public static Entry entry(zombie.iso.IsoChunk c){return entries.computeIfAbsent(c,k->new Entry());}public static Level level(zombie.iso.IsoChunk c,int z){var e=entry(c);if(e.levels[z+32]==null)e.levels[z+32]=new Level();return e.levels[z+32];}public static viewpoint.render.ChunkMeshData meshOn(zombie.iso.IsoGridSquare s){return level(s.getChunk(),s.getZ()).data;}public static boolean packsOn(zombie.iso.IsoGridSquare s){return true;}public static final class Entry{final Level[] levels=new Level[64];}public static final class Level{public boolean dirty,evicted;public boolean modelsNear=true;public java.util.ArrayList<zombie.iso.IsoObject> modelled=new java.util.ArrayList<>();public long version;public viewpoint.render.ChunkMeshData data;}}
